import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchUserData, updateUser, searchUsersByName, setSelectedUser } from '../auth/AuthSlice';
import EditProfile from './EditProfile';
//import "./searchProfile.css"
import AlertSetting from './alertSetting/AlertSetting';
import { DiscAssessment } from './discassessment/DiscAssessment';
import { Modal, OverlayTrigger } from "react-bootstrap";
import { Tooltip } from 'antd';
import Select, { StylesConfig } from 'react-select';
import PhoneInput from 'react-phone-input-2'
import 'react-phone-input-2/lib/style.css'
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const Profile = () => {
  const user = useSelector((state) => state.auth.user) || {
    "id": 1,
    "name": "John Doe",
    "email": "prady7119@gmail.com",
    "user_password": "$2b$10$i07gNaICR7kJSdhL6wap6uuWa21S/Ij4rnur21YvlbaV7MUj5wO56",
    "user_photo": "https://example.com/photo.jpg",
    "phone_number": "1234567890",
    "p_isd": "+1",
    "whatsapp_no": "1234567890",
    "w_isd": "+1",
    "otp": "123456",
    "position": "Developer",
    "is_login": false,
    "is_verified": true,
    "company_id": 1,
    "departments_id": 1,
    "status": true,
    "remember_token": null,
    "user_roles": "administration",
    "department": "IT",
    "notes": "Some notes here",
    "twitter_url": "https://twitter.com/johndoe",
    "linkedin_url": "https://linkedin.com/in/johndoe",
    "date_of_birth": "1990-01-01",
    "hire_date": "2020-01-01",
    "hobbies": "Coding, Music",
    "D": 10,
    "I": 20,
    "S": 30,
    "C": 40,
    "D2": 50,
    "I2": 60,
    "S2": 70,
    "C2": 80,
    "assignTaskAlert": true,
    "taskDueTodayAlert": true,
    "changeDueDateAlert": false,
    "completeTaskAlert": true,
    "stuckAlert": false,
    "unstuckAlert": true,
    "weeklyAlert": true,
    "created_at": "2024-08-16T10:07:17.000Z",
    "updated_at": "2024-08-16T10:07:17.000Z"
  };
  const searchResults = useSelector((state) => state.auth.searchResults);
  const dispatch = useDispatch();
  const [isEditing, setIsEditing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  // Edit User Profile Modal start
  const [showEditProfileModal, setShowEditProfileModal] = useState(false);
  const handleCloseEditProfileModal = () => setShowEditProfileModal(false);
  const handleShowEditProfileModal = () => setShowEditProfileModal(true);

  // Change User Image Modal start
  const [showChangeUserImageModal, setShowChangeUserImageModal] = useState(false);
  const handleCloseChangeUserImageModal = () => setShowChangeUserImageModal(false);
  const handleShowChangeUserImageModal = () => setShowChangeUserImageModal(true);

  useEffect(() => {
    dispatch(fetchUserData());
  }, [dispatch]);

  const handleEditClick = () => {
    setIsEditing(true);
    setShowEditProfileModal(true);
  };

  const handleFormClose = () => {
    setIsEditing(false);
  };

  const handleUpdateUser = async (updatedUserData) => {
    await dispatch(updateUser({ Id: user.id, ...updatedUserData }));
    setIsEditing(false);
    dispatch(fetchUserData());
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
    if (e.target.value) {
      dispatch(searchUsersByName(e.target.value));
    }
  };

  const handleUserSelect = async (userId) => {
    await dispatch(setSelectedUser(userId));
    setSearchTerm(''); // Clear search input
  };

  if (!user) {
    return <div>Loading...</div>;
  }

  return (
    <>
      <div className="titleBar bg-white py-2 px-4 d-flex align-items-center flex-wrap shadow">
        <div className="pageTitle me-2">User Profiles</div>
      </div>
      <div className='p-4'>
        <div className='row'>
          <div className='col-md-6'>
            <div className='form-group'>
              <label className='form-label'>Search Users</label>
              <input
                className="form-control"
                placeholder="Search by name"
                value={searchTerm}
                onChange={handleSearchChange}
              />
            </div>

            {searchTerm && (
              <div className="search-results shadow-sm">
                {searchResults ? (
                  <ul>
                    {searchResults.map((result) => (
                      <li key={result.id} onClick={() => handleUserSelect(result.id)}>
                        {result.name}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p>No results found</p>
                )}
              </div>
            )}

          </div>
          <div className='col-12'>
            <div className="card">
              <div className="card-body">
                <div className='d-flex flex-wrap'>
                  <div className="user-image" >
                    {/* <img src={user.user_photo} alt="User Profile" /> */}
                    <div className='image-overlay' onClick={handleShowChangeUserImageModal}>
                      <i class="fi fi-br-picture"></i>
                    </div>
                    <span>
                      <img src="data:image/png;base64," alt="User Profile" />
                    </span>
                  </div>
                  <div className='user-desc-wrap'>
                    <div className='d-flex justify-content-between'>
                      <h5>{user.name}</h5>
                      <Tooltip title='Edit Profile'>
                        <button className="icon-btn" onClick={handleEditClick}>
                          <i class="fi fi-br-pencil"></i>
                        </button>
                        {/* <button className="icon-btn" onClick={handleShowEditProfileModal}>
                          <i class="fi fi-br-pencil"></i>
                        </button> */}
                      </Tooltip>
                     
                        
                    </div>
                    <div className='row'>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>Email:</label>
                          <p className="mb-0">{user.email}</p>
                        </div>
                      </div>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>Phone:</label>
                          <p className="mb-0">{user.phone_number}</p>
                        </div>
                      </div>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>Twitter:</label>
                          <p className="mb-0">{user.x}</p>
                        </div>
                      </div>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>Facebook:</label>
                          <p className="mb-0">{user.facebook}</p>
                        </div>
                      </div>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>LinkedIn:</label>
                          <p className="mb-0">{user.linkedin}</p>
                        </div>
                      </div>
                      <div className='col-lg-4 col-md-6'>
                        <div className='form-group'>
                          <label className='form-label'>User Roles:</label>
                          <p className="mb-0">{user.user_roles}</p>
                        </div>
                      </div>
                      <div className='col-lg-12 col-md-12'>
                        <div className='form-group'>
                          <label className='form-label'>Notes:</label>
                          <p className="mb-0">{user.user_notes}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

              </div>
            </div>
          </div>
          <div className='col-12'>
            <AlertSetting user={user} onClose={handleFormClose} onUpdateUser={handleUpdateUser} />
          </div>
          <div className='col-12'>
            <DiscAssessment user={user} onUpdateUser={handleUpdateUser} />
          </div>
        </div>
        <div >
          {isEditing && <EditProfile user={user}
            onClose={handleFormClose}
            onUpdateUser={handleUpdateUser}
            showEditProfileModal={showEditProfileModal}
            handleCloseEditProfileModal={handleCloseEditProfileModal}
            showChangeUserImageModal={showChangeUserImageModal}
            handleCloseChangeUserImageModal={handleCloseChangeUserImageModal}
          />

          }
        </div>
      </div>

    </>
  );
}

export default Profile;
